using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.Text;

namespace SourceGen.Ioc.Test.Infrastructure;

/// <summary>
/// Tests of the test helpers, with <see cref="FakeGenerator"/> and hand-written "generated" files.
/// </summary>
public class TestHelperTests
{
    private const string Header = """
        // <auto-generated/>
        #nullable enable annotations
        #nullable disable warnings
        #pragma warning disable SGIOCEXP001

        """;

    private const string Attribute = """[global::System.CodeDom.Compiler.GeneratedCode("SourceGen.Ioc", "1.0.0")]""";

    /// <summary>Checks <paramref name="generated"/> as if the generator had added it next to <paramref name="user"/>.</summary>
    private static IReadOnlyList<string> CheckRules(string user, string generated)
    {
        Compilation compilation = SourceGeneratorTestHelper.CreateCompilation([user, generated]);
        return GeneratedCodeRules.Check(compilation, [compilation.SyntaxTrees.Last()]);
    }

    [Test]
    public async Task RunGenerator_FakeGenerator_OutputCompilesAndFollowsRules()
    {
        GeneratorTestResult result = SourceGeneratorTestHelper.RunGenerator<FakeGenerator>("public partial class FakePartial;");

        await result.VerifyCompilableAsync();
        await Verify(result.GetGeneratedSource("FakePartial.g.cs"));
    }

    [Test]
    public async Task GeneratedCodeRules_ValidFile_NoProblem()
    {
        IReadOnlyList<string> problems = CheckRules("public partial class Foo;", $$"""
            {{Header}}
            partial class Foo
            {
                {{Attribute}}
                private readonly int field;

                {{Attribute}}
                public int M() { int x = field; return x; }

                {{Attribute}}
                public sealed class Nested;
            }

            {{Attribute}}
            internal static class Helper
            {
                public static int Value => 1;
            }
            """);

        await Assert.That(problems).IsEmpty();
    }

    [Test]
    public async Task GeneratedCodeRules_AttributeOnUserPartial_Reported()
    {
        IReadOnlyList<string> problems = CheckRules("public partial class Foo;", $$"""
            {{Header}}
            {{Attribute}}
            partial class Foo
            {
                {{Attribute}}
                public void M() { }
            }
            """);

        await Assert.That(problems).HasSingleItem();
        await Assert.That(problems[0]).Contains("partial declaration of user type 'Foo' has [GeneratedCode]");
    }

    [Test]
    public async Task GeneratedCodeRules_NestedUserPartial_ChecksMembersOfInnerType()
    {
        IReadOnlyList<string> problems = CheckRules("public partial class Outer { public partial class Inner; }", $$"""
            {{Header}}
            partial class Outer
            {
                partial class Inner
                {
                    public void M() { }
                }
            }
            """);

        await Assert.That(problems).HasSingleItem();
        await Assert.That(problems[0]).Contains("member 'M' of 'Inner' has no [GeneratedCode]");
    }

    [Test]
    public async Task GeneratedCodeRules_GeneratorTypeWithoutAttributeOrWithFourPartVersion_Reported()
    {
        IReadOnlyList<string> problems = CheckRules("public class User;", $$"""
            {{Header}}
            internal static class Missing;

            [global::System.CodeDom.Compiler.GeneratedCode("SourceGen.Ioc", "1.0.0.5")]
            internal static class WrongVersion;
            """);

        await Assert.That(problems).Count().IsEqualTo(2);
        await Assert.That(problems[0]).Contains("type 'Missing' has [GeneratedCode] on 0 of its 1");
        await Assert.That(problems[1]).Contains("type 'WrongVersion' has [GeneratedCode] with wrong arguments");
    }

    [Test]
    public async Task GeneratedCodeRules_VarAndReflection_Reported()
    {
        IReadOnlyList<string> problems = CheckRules("public class User;", $$"""
            {{Header}}
            {{Attribute}}
            internal static class Bad
            {
                public static object M()
                {
                    var x = 1;
                    object o = global::System.Activator.CreateInstance(typeof(object))!;
                    global::System.Type t = typeof(global::System.Collections.Generic.List<>).MakeGenericType(typeof(int));
                    global::System.Array a = global::System.Array.CreateInstance(typeof(int), x);
                    return (o, t, a);
                }
            }
            """);

        await Assert.That(problems).Count().IsEqualTo(4);
        await Assert.That(problems[0]).Contains("'var'");
        await Assert.That(problems.Skip(1).All(static p => p.Contains("reflection '", StringComparison.Ordinal))).IsTrue();
    }

    [Test]
    public async Task GeneratedCodeRules_HeaderMissing_Reported()
    {
        IReadOnlyList<string> problems = CheckRules("public class User;", $$"""
            // <auto-generated/>

            {{Attribute}}
            internal static class Helper;
            """);

        await Assert.That(problems).Count().IsEqualTo(3);
        await Assert.That(problems[0]).Contains("line 2");
    }

    [Test]
    public async Task DiagnosticMarkup_Parse_RemovesMarkersAndRecordsSpans()
    {
        (IReadOnlyList<string> sources, IReadOnlyList<ExpectedDiagnostic> expected) = DiagnosticMarkup.Parse(
            "class {|A1:Foo|} { }",
            "class Bar { int {|B2:x|}; }");

        await Assert.That(sources).IsEquivalentTo(["class Foo { }", "class Bar { int x; }"]);
        await Assert.That(expected).IsEquivalentTo([
            new ExpectedDiagnostic("A1", "File0.cs", new TextSpan(6, 3)),
            new ExpectedDiagnostic("B2", "File1.cs", new TextSpan(16, 1)),
        ]);
    }

    [Test]
    public async Task VerifyDiagnostics_FakeWarnAtMarkedSpan_Passes()
    {
        (IReadOnlyList<string> sources, IReadOnlyList<ExpectedDiagnostic> expected) = DiagnosticMarkup.Parse(
            "public class Other;",
            "public class {|FAKE001:FakeWarn|};");

        GeneratorTestResult result = SourceGeneratorTestHelper.RunGenerator<FakeGenerator>(sources);

        await result.VerifyDiagnosticsAsync(expected, idPrefix: "FAKE");
        await Assert.That(result.GetDiagnostic("FAKE001").GetMessage(System.Globalization.CultureInfo.InvariantCulture)).IsEqualTo("Warning on 'FakeWarn'");
    }

    [Test]
    public async Task DiagnosticMarkup_Compare_ReportsMissingAndUnexpected()
    {
        (IReadOnlyList<string> sources, IReadOnlyList<ExpectedDiagnostic> expected) = DiagnosticMarkup.Parse("public class {|FAKE002:FakeWarn|};");

        GeneratorTestResult result = SourceGeneratorTestHelper.RunGenerator<FakeGenerator>(sources);
        IReadOnlyList<string> differences = DiagnosticMarkup.Compare(expected, result.Diagnostics, "FAKE");

        await Assert.That(differences).Count().IsEqualTo(2);
        await Assert.That(differences[0]).StartsWith("missing: FAKE002");
        await Assert.That(differences[1]).StartsWith("unexpected: FAKE001");
    }

    [Test]
    public async Task Diagnostics_Pragma_SuppressesWarningAndInfoButNotError()
    {
        GeneratorTestResult result = SourceGeneratorTestHelper.RunGenerator<FakeGenerator>("""
            #pragma warning disable FAKE001, FAKE002, FAKE003
            public class FakeWarn;
            public class FakeError;
            public class FakeInfo;
            """);

        await Assert.That(result.ReportedDiagnostics.Select(static d => d.Id)).IsEquivalentTo(["FAKE002"]);
    }

    [Test]
    [Arguments(false)]
    [Arguments(true)]
    public async Task Diagnostics_SeverityOptionSuppress_RemovesWarningButNotError(bool perFile)
    {
        Dictionary<string, ReportDiagnostic> suppress = new() { ["FAKE001"] = ReportDiagnostic.Suppress, ["FAKE002"] = ReportDiagnostic.Suppress };
        GeneratorRunOptions options = perFile
            ? new() { FileDiagnosticOptions = new Dictionary<string, IReadOnlyDictionary<string, ReportDiagnostic>> { ["File0.cs"] = suppress } }
            : new() { DiagnosticOptions = suppress };

        GeneratorTestResult result = SourceGeneratorTestHelper.RunGenerator<FakeGenerator>("public class FakeWarn; public class FakeError;", options);

        await Assert.That(result.ReportedDiagnostics.Select(static d => d.Id)).IsEquivalentTo(["FAKE002"]);
    }

    [Test]
    public async Task Diagnostics_SeverityOptionError_RaisesWarning()
    {
        GeneratorTestResult result = SourceGeneratorTestHelper.RunGenerator<FakeGenerator>(
            "public class FakeWarn;",
            new() { DiagnosticOptions = new Dictionary<string, ReportDiagnostic> { ["FAKE001"] = ReportDiagnostic.Error } });

        await Assert.That(result.GetDiagnostic("FAKE001").Severity).IsEqualTo(DiagnosticSeverity.Error);
    }

    [Test]
    public async Task Incremental_UnrelatedEdit_StepIsCached()
    {
        GeneratorTestResult first = SourceGeneratorTestHelper.RunGenerator<FakeGenerator>(
            ["public partial class FakePartial;", "public class Other;"],
            new() { TrackSteps = true });

        GeneratorTestResult second = IncrementalTestHelper.RunAgainWithEdit(first, 1, "public class Other { public int X; }");

        await IncrementalTestHelper.VerifyNotRunAgainAsync(second, FakeGenerator.ModelStep);
    }

    [Test]
    public async Task Incremental_RelatedEdit_StepRunsAgain()
    {
        GeneratorTestResult first = SourceGeneratorTestHelper.RunGenerator<FakeGenerator>(
            ["public partial class FakePartial;"],
            new() { TrackSteps = true });

        GeneratorTestResult second = IncrementalTestHelper.RunAgainWithEdit(first, 0, "public partial class FakePartialRenamed;");

        await Assert.That(IncrementalTestHelper.GetReasons(second, FakeGenerator.ModelStep))
            .Contains(static r => r is IncrementalStepRunReason.New or IncrementalStepRunReason.Modified);
    }

    [Test]
    public async Task FindForbiddenValues_ModelWithoutSymbols_NoProblem()
    {
        GeneratorTestResult result = SourceGeneratorTestHelper.RunGenerator<FakeGenerator>(
            "public partial class FakePartial; public class FakeWarn;",
            new() { TrackSteps = true });

        await Assert.That(IncrementalTestHelper.FindForbiddenValues(result, FakeGenerator.ModelStep)).IsEmpty();
    }

    [Test]
    public async Task FindForbiddenValues_SymbolInStep_Reported()
    {
        GeneratorTestResult result = SourceGeneratorTestHelper.RunGenerator<LeakyGenerator>("public class Foo;", new() { TrackSteps = true });

        IReadOnlyList<string> problems = IncrementalTestHelper.FindForbiddenValues(result, LeakyGenerator.Step);

        await Assert.That(problems).IsNotEmpty();
        await Assert.That(problems[0]).StartsWith($"{LeakyGenerator.Step}: ISymbol");
    }

    [Test]
    public async Task CompileReference_ImageAndCompilationReference_GiveSameOutput()
    {
        ReferencedAssembly library = SourceGeneratorTestHelper.CompileReference<FakeGenerator>(
            "public partial class FakePartialLib;",
            new() { AssemblyName = "Lib" });
        const string App = "public partial class FakePartialApp { public int Use() => new FakePartialLib().Generated(); }";

        GeneratorTestResult withImage = SourceGeneratorTestHelper.RunGenerator<FakeGenerator>(App, new() { References = [library.Image] });
        GeneratorTestResult withCompilation = SourceGeneratorTestHelper.RunGenerator<FakeGenerator>(App, new() { References = [library.CompilationReference] });

        await withImage.VerifyCompilableAsync();
        await withCompilation.VerifyCompilableAsync();
        await Assert.That(withImage.GetGeneratedSource("FakePartialApp")).IsEqualTo(withCompilation.GetGeneratedSource("FakePartialApp"));
    }

    [Test]
    public async Task SnapshotHelper_Members_ReturnsOnlyNamedMembers()
    {
        const string Source = """
            partial class Foo
            {
                private int a;

                public int B() => a;

                public int C() => 2;
            }
            """;

        await Assert.That(SnapshotHelper.Members(Source, "B")).IsEqualTo("    public int B() => a;");
        await Assert.That(() => SnapshotHelper.Members(Source, "Missing")).Throws<ArgumentException>();
    }

    [Test]
    public async Task Diagnostics_FileSeverityOptionOnOtherFile_DoesNotApply()
    {
        Dictionary<string, ReportDiagnostic> suppress = new() { ["FAKE001"] = ReportDiagnostic.Suppress };

        GeneratorTestResult result = SourceGeneratorTestHelper.RunGenerator<FakeGenerator>(
            ["public class FakeWarn;", "public class Other;"],
            new() { FileDiagnosticOptions = new Dictionary<string, IReadOnlyDictionary<string, ReportDiagnostic>> { ["File1.cs"] = suppress } });

        await Assert.That(result.ReportedDiagnostics.Select(static d => d.Id)).IsEquivalentTo(["FAKE001"]);
    }

    [Test]
    public async Task RunGenerator_GeneratorThrows_Throws()
    {
        InvalidOperationException? exception = await Assert.That(() => SourceGeneratorTestHelper.RunGenerator<ThrowingGenerator>("public class Foo;"))
            .Throws<InvalidOperationException>();

        await Assert.That(exception!.InnerException!.Message).IsEqualTo("boom");
    }

    [Test]
    public async Task DiagnosticMarkup_Compare_DuplicateReportIsUnexpected()
    {
        (IReadOnlyList<string> sources, IReadOnlyList<ExpectedDiagnostic> expected) = DiagnosticMarkup.Parse("public class {|FAKE001:FakeTwice|};");

        GeneratorTestResult result = SourceGeneratorTestHelper.RunGenerator<FakeGenerator>(sources);
        IReadOnlyList<string> differences = DiagnosticMarkup.Compare(expected, result.Diagnostics, "FAKE");

        await Assert.That(differences).HasSingleItem();
        await Assert.That(differences[0]).StartsWith("unexpected: FAKE001");
    }

    [Test]
    public async Task GeneratedCodeRules_OtherReflectionForms_Reported()
    {
        IReadOnlyList<string> problems = CheckRules("public class User;", $$"""
            {{Header}}
            {{Attribute}}
            internal static class Bad
            {
                public static object M(global::System.IServiceProvider sp)
                {
                    object a = global::Microsoft.Extensions.DependencyInjection.ActivatorUtilities.CreateInstance(sp, typeof(object));
                    global::System.Type? t = global::System.Type.GetType("System.Object");
                    object b = typeof(object).GetMethods();
                    global::System.Func<global::System.Type, object?> f = global::System.Activator.CreateInstance;
                    global::System.Reflection.AssemblyName n = new("x");
                    return (a, t, b, f, n);
                }
            }
            """);

        await Assert.That(problems).Count().IsEqualTo(5);
        await Assert.That(problems.All(static p => p.Contains("reflection", StringComparison.Ordinal))).IsTrue();
    }

    [Test]
    public async Task GeneratedCodeRules_TypeofAndObjectGetType_NoProblem()
    {
        IReadOnlyList<string> problems = CheckRules("public class User;", $$"""
            {{Header}}
            {{Attribute}}
            internal static class Good
            {
                public static global::System.Type M(object o) => o.GetType() == typeof(int) ? typeof(string) : o.GetType();
            }
            """);

        await Assert.That(problems).IsEmpty();
    }

    [Test]
    public async Task GeneratedCodeRules_TopLevelDelegateWithoutAttribute_Reported()
    {
        IReadOnlyList<string> problems = CheckRules("public class User;", $$"""
            {{Header}}
            internal delegate int GenDelegate();
            """);

        await Assert.That(problems).HasSingleItem();
