    [Test]
    [Arguments(0, 1)]
    [Arguments(1, 0)]
    [Arguments(2, 1)]
    public async Task GeneratedCodeRules_GeneratorTypeSplitInTwoDeclarations_NeedsExactlyOneAttribute(int attributes, int expectedProblems)
    {
        IReadOnlyList<string> problems = CheckRules("public class User;", $$"""
            {{Header}}
            {{(attributes >= 1 ? Attribute : "")}}
            internal static partial class Split
            {
                public static int A => 1;
            }

            {{(attributes >= 2 ? Attribute : "")}}
            internal static partial class Split
            {
                public static int B => 2;
            }
            """);

        await Assert.That(problems).Count().IsEqualTo(expectedProblems);
    }

